package com.taller.portal;
import static org.junit.jupiter.api.Assertions.*;
import com.taller.portal.repository.VpicCatalogoRepository; import com.taller.portal.service.VpicImportService; import java.nio.file.Path; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.*; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.core.io.ClassPathResource; import org.springframework.jdbc.core.JdbcTemplate;
/** Verifica importación idempotente, normalización, omitidos y búsquedas del fixture vPIC local. */
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:vpic;MODE=MySQL;DB_CLOSE_DELAY=-1","spring.datasource.driver-class-name=org.h2.Driver","spring.datasource.username=sa","spring.datasource.password="}) class VpicImportServiceTest {
 @Autowired VpicImportService servicio; @Autowired VpicCatalogoRepository catalogo; @Autowired JdbcTemplate jdbc;
 /** Limpia el catálogo aislado antes de cada fixture. @return void. */ @BeforeEach void limpiar(){jdbc.update("delete from vpic_modelo");jdbc.update("delete from vpic_marca");}
 /** Importa el fixture y confirma normalización, omitidos y cobertura idempotente. @throws Exception si el fixture no está disponible. */ @Test void importaFixtureNormalizaYOmitidos()throws Exception{Path archivo=new ClassPathResource("vpic/catalogo-fixture.json").getFile().toPath();var primera=servicio.importar(archivo);assertEquals(2,primera.marcasNuevas());assertEquals(2,primera.modelosNuevos());assertEquals(3,primera.omitidos());assertEquals("NISSAN",catalogo.buscarMarcas("NIS").getFirst().nombre);var segunda=servicio.importar(archivo);assertEquals(0,segunda.marcasNuevas());assertEquals(0,segunda.modelosNuevos());assertEquals(2,segunda.marcasExistentes());}
 /** Busca por prefijo en marca y modelo con el límite encapsulado en el repositorio. @throws Exception si el fixture no puede importarse. */ @Test void buscaPorPrefijoMarcaYModelo()throws Exception{servicio.importar(new ClassPathResource("vpic/catalogo-fixture.json").getFile().toPath());var marca=catalogo.buscarMarcas("TOY").getFirst();assertEquals("TOYOTA",marca.nombre);assertEquals("COROLLA",catalogo.buscarModelos(marca.id,"COR").getFirst().nombre);}
/** Omite de forma segura cada registro que carece de los campos obligatorios de vPIC. @throws Exception si el fixture no puede importarse. */ @Test void omiteCamposFaltantes(){assertDoesNotThrow(()->{var resultado=servicio.importar(new ClassPathResource("vpic/catalogo-incompleto-fixture.json").getFile().toPath());assertEquals(3,resultado.omitidos());assertEquals(1,resultado.marcasNuevas());assertEquals(0,resultado.modelosNuevos());});}
}
